// Fetch GitHub activity for the past 7 days
const repo = $input.first().json.GITHUB_REPO;
const token = $input.first().json.GITHUB_TOKEN;
const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

const headers = {
  'Accept': 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-weekly-summary/1.0',
};
if (token && token !== '$env.GITHUB_TOKEN') {
  headers['Authorization'] = `Bearer ${token}`;
}

async function githubGet(path) {
  const res = await fetch(`https://api.github.com${path}`, { headers });
  if (!res.ok) throw new Error(`GitHub API error ${res.status} for ${path}`);
  return res.json();
}

// Parallel fetch of commits, closed issues, merged PRs
const [commits, issues, prs, repoInfo] = await Promise.all([
  githubGet(`/repos/${repo}/commits?since=${since}&per_page=50`).catch(() => []),
  githubGet(`/repos/${repo}/issues?state=closed&since=${since}&per_page=50`).catch(() => []),
  githubGet(`/repos/${repo}/pulls?state=closed&sort=updated&direction=desc&per_page=50`).catch(() => []),
  githubGet(`/repos/${repo}`).catch(() => ({})),
]);

// Filter PRs merged in last 7 days
const mergedPrs = prs.filter(pr =>
  pr.merged_at && new Date(pr.merged_at) >= new Date(Date.now() - 7 * 24 * 60 * 60 * 1000)
);

// Real issues (not PRs)
const realIssues = issues.filter(i => !i.pull_request);

// Top contributors by commit count
const authorMap = {};
for (const c of commits) {
  const name = c.commit?.author?.name || 'Unknown';
  authorMap[name] = (authorMap[name] || 0) + 1;
}
const topContributors = Object.entries(authorMap)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, count]) => `${name} (${count})`);

// Build commit summary (most recent 10)
const commitSummary = commits.slice(0, 10).map(c => ({
  sha: c.sha?.slice(0, 7),
  message: c.commit?.message?.split('\n')[0]?.slice(0, 80),
  author: c.commit?.author?.name,
  date: c.commit?.author?.date?.slice(0, 10),
}));

// Build PR summary
const prSummary = mergedPrs.slice(0, 10).map(pr => ({
  number: pr.number,
  title: pr.title?.slice(0, 80),
  author: pr.user?.login,
  merged_at: pr.merged_at?.slice(0, 10),
}));

// Build issues summary
const issuesSummary = realIssues.slice(0, 10).map(i => ({
  number: i.number,
  title: i.title?.slice(0, 80),
  closed_at: i.closed_at?.slice(0, 10),
}));

return [{
  json: {
    ...$input.first().json,
    repo,
    since: since.slice(0, 10),
    stats: {
      commits: commits.length,
      merged_prs: mergedPrs.length,
      closed_issues: realIssues.length,
      top_contributors: topContributors,
    },
    commit_summary: commitSummary,
    pr_summary: prSummary,
    issues_summary: issuesSummary,
    repo_stars: repoInfo.stargazers_count || 0,
    repo_description: repoInfo.description || '',
  }
}];

