const data = $input.first().json;

// Extract Claude's narrative from API response
const narrative = data.content?.[0]?.text ||
  data.choices?.[0]?.message?.content ||
  '(narrative unavailable)';

// Keep original config fields
const config = {
  GITHUB_REPO: data.GITHUB_REPO || '',
  LANGUAGE: data.LANGUAGE || 'EN',
  DELIVERY: data.DELIVERY || 'discord',
  DISCORD_WEBHOOK_URL: data.DISCORD_WEBHOOK_URL || '',
  SLACK_WEBHOOK_URL: data.SLACK_WEBHOOK_URL || '',
  repo: data.repo || data.GITHUB_REPO || '',
  since: data.since || '',
  stats: data.stats || {},
  repo_stars: data.repo_stars || 0,
};

const weekLabel = new Date().toLocaleDateString('en-CA'); // YYYY-MM-DD
const statsLine = config.LANGUAGE === 'FR'
  ? `📊 **${config.stats.commits || 0}** commits · **${config.stats.merged_prs || 0}** PRs fusionnées · **${config.stats.closed_issues || 0}** issues fermées`
  : `📊 **${config.stats.commits || 0}** commits · **${config.stats.merged_prs || 0}** PRs merged · **${config.stats.closed_issues || 0}** issues closed`;

const contributorsLine = (config.stats.top_contributors || []).length > 0
  ? (config.LANGUAGE === 'FR' ? '👥 Top contributeurs: ' : '👥 Top contributors: ') + config.stats.top_contributors.join(', ')
  : '';

// Discord payload
const discordPayload = {
  embeds: [{
    title: config.LANGUAGE === 'FR'
      ? `📅 Résumé hebdomadaire — ${config.repo}`
      : `📅 Weekly Dev Summary — ${config.repo}`,
    description: narrative.slice(0, 4000),
    color: 0x5865F2,
    fields: [
      { name: '\u200b', value: statsLine, inline: false },
      ...(contributorsLine ? [{ name: '\u200b', value: contributorsLine, inline: false }] : []),
    ],
    footer: {
      text: config.LANGUAGE === 'FR'
        ? `Semaine du ${config.since} · ${config.repo_stars}⭐`
        : `Week of ${config.since} · ${config.repo_stars}⭐`,
    },
    timestamp: new Date().toISOString(),
  }]
};

// Slack payload (mrkdwn)
const slackText = (config.LANGUAGE === 'FR'
  ? `*📅 Résumé hebdomadaire — ${config.repo}*\n\n`
  : `*📅 Weekly Dev Summary — ${config.repo}*\n\n`
) + narrative + `\n\n${statsLine}` + (contributorsLine ? `\n${contributorsLine}` : '');

const slackPayload = {
  text: slackText.slice(0, 3000),
  unfurl_links: false,
};

return [{
  json: {
    ...config,
    narrative,
    discord_payload: JSON.stringify(discordPayload),
    slack_payload: JSON.stringify(slackPayload),
    week_label: weekLabel,
  }
}];
